style.css:
@-moz-document domain("youtube.com") {
/* General background and font */
  body, ytd-app {
    background-color: #1a1a1a !important;
    color: #dcd4b0 !important;
    font-family: "Georgia", "Garamond", "Times New Roman", serif !important;
  }

  /* Header */
  #masthead-container, ytd-masthead {
    background-color: #2b2b2b !important;
    border-bottom: 1px solid #444 !important;
  }

  /* Search bar */
  input#search {
    background-color: #3a3a3a !important;
    color: #f5f0e6 !important;
    border: 1px solid #777 !important;
  }

  /* Sidebar / Navigation */
  ytd-guide-section-renderer,
  ytd-mini-guide-renderer,
  ytd-guide-entry-renderer {
    background-color: #222 !important;
    color: #c6baa6 !important;
  }

  /* Video titles and links */
  a, h3, #video-title {
    color: #d8cfa7 !important;
  }

  /* Thumbnails hover effect */
  ytd-thumbnail:hover {
    filter: sepia(20%) brightness(90%) !important;
    transform: scale(1.02);
    transition: all 0.3s ease-in-out;
  }

  /* Video player darkened */
  ytd-player {
    background-color: #000 !important;
  }

  /* Scrollbar */
  ::-webkit-scrollbar {
    width: 12px;
  }
  ::-webkit-scrollbar-track {
    background: #1a1a1a;
  }
  ::-webkit-scrollbar-thumb {
    background: #5a4e3b;
    border-radius: 6px;
  }

  /* Buttons */
  ytd-button-renderer {
    background-color: #3a3024 !important;
    color: #e6decf !important;
    border-radius: 3px;
  }

  /* Like/Dislike & Sub */
  ytd-toggle-button-renderer,
  ytd-subscribe-button-renderer {
    background-color: #403831 !important;
    color: #c1b8a1 !important;
  }

  /* Footer */
  #footer {
    background-color: #2b2b2b !important;
  }

  /* Magical detail: background stars */
  body::before {
    content: "";
    background: url("https://i.imgur.com/0DQuSbp.png") repeat;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    opacity: 0.05;
    z-index: -1;
  }
}
